    "author": "危颖,余国庆,方亚东",
    "description": "走进湖北省嘉鱼县潘家湾镇蔬菜数字化健康栽培展示区，通过光伏电子屏就能实时查看园区内的水肥、土壤、病虫害等种植信息。园区内还应用了水肥一体化技术，省肥30%，也有机械化流水作业可以大幅降低人工成本，同时物联网与智能灌溉系统还让生产效率倍增。数字化的栽培技术，正让蔬菜种植从“靠天”变成“靠数据”。 记者：危颖、方亚东、余国庆 摄制：卢建 新华社音视频部制作",
