    "description": "此生的脆弱无可消解。每个人都只有一次生命，时间一去不返，死亡是不可逆转的终点。那么，在只有一次的此生中，我们为何付出、为谁奋斗、何以幸福？2019年，耶鲁大学比尔吉特·鲍德温比较文学、人文学与哲学讲席教授马丁·黑格隆德（Martin Hägglund）的《夺回时间：世俗信仰与精神自由》（This Life: Secular Faith and Spiritual Freedom）一经出版，便在英语世界引发关注。这部厚达四百余页的著作，将…",
    "content": "此生的脆弱无可消解。每个人都只有一次生命，时间一去不返，死亡是不可逆转的终点。那么，在只有一次的此生中，我们为何付出、为谁奋斗、何以幸福？2019年，耶鲁大学比尔吉特·鲍德温比较文学、人文学与哲学讲席教授马丁·黑格隆德（Martin Hägglund）的《夺回时间：世俗信仰与精神自由》（ This Life: Secular Faith and Spiritual Freedom ）一经出版，便在英语世界引发关注。这部厚达四百余页的著作，将奥古斯丁、黑格尔、克尔凯郭尔的时间哲学反思与马克思的政治经济学批判熔于一炉，…"
