    "description": "新华社纽约9月16日电（记者刘亚南）据美国白宫16日发布的消息，美国总统特朗普当日签署一份总统备忘录，将源自加拿大的产品排除出美政府采购计划。 根据备忘录，特朗普指示白宫管理和预算办公室主任和美国贸易代表与其他部门一起识别并采取一切法律允许的措施，把源自加拿大的产品排除在联邦民用采购体系之外。白宫管理和预算办公室主任还应告知其他部门有关美国国内替代产品的信息。 特朗普还指示美国贸易代表继续监控加拿大联邦和省级政府采购过程中给予美国产品的…",
    "content": "新华社纽约9月16日电（记者刘亚南）据美国白宫16日发布的消息，美国总统特朗普当日签署一份总统备忘录，将源自加拿大的产品排除出美政府采购计划。 根据备忘录，特朗普指示白宫管理和预算办公室主任和美国贸易代表与其他部门一起识别并采取一切法律允许的措施，把源自加拿大的产品排除在联邦民用采购体系之外。白宫管理和预算办公室主任还应告知其他部门有关美国国内替代产品的信息。 特朗普还指示美国贸易代表继续监控加拿大联邦和省级政府采购过程中给予美国产品的待遇。 备忘录称，加拿大政府的“购买加拿大”政策为美国企业进入加政府采购市场设置…"
