    "title": "土耳其称伊朗支持土方解散库尔德工人党",
    "link": "http://www.news.cn/20260917/b94316035eef408eaeb609bf0a69d3f5/c.html",
    "pub_date": "2026-09-17 07:17:39",
    "author": "霍丹彤",
    "description": "新华社安卡拉9月16日电（记者霍丹彤）土耳其内政部16日发表声明称，伊朗支持土耳其解散库尔德工人党及其分支的相关行动。 声明称，土耳其内政部长奇夫特奇和伊朗内政部长莫梅尼当天在土首都安卡拉举行会谈。奇夫特奇称，解散库尔德工人党及其在叙利亚和伊拉克的分支，对于地区和平至关重要；同时，将伊朗境内活动的库尔德斯坦自由生活党纳入这一进程同样重要。 莫梅尼呼吁土耳其、伊拉克、伊朗和叙利亚合作，推动库尔德工人党及其分支放下武器，实现库尔德问题的根本…",
    "content": "新华社安卡拉9月16日电（记者霍丹彤）土耳其内政部16日发表声明称，伊朗支持土耳其解散库尔德工人党及其分支的相关行动。 声明称，土耳其内政部长奇夫特奇和伊朗内政部长莫梅尼当天在土首都安卡拉举行会谈。奇夫特奇称，解散库尔德工人党及其在叙利亚和伊拉克的分支，对于地区和平至关重要；同时，将伊朗境内活动的库尔德斯坦自由生活党纳入这一进程同样重要。 莫梅尼呼吁土耳其、伊拉克、伊朗和叙利亚合作，推动库尔德工人党及其分支放下武器，实现库尔德问题的根本解决。 声明说，双方还就加强边境安全合作、共同打击有组织犯罪、毒品走私和非法移民…"
