    "description": "多名日本历史学者、民间和平人士9月16日在东京围绕九一八事变爆发95周年举行研讨会。与会者就“历史记忆与传承”这一主题，围绕战争记忆、加害责任以及和平理念传承等展开交流。 此次研讨会分东京和长春两个会场，以视频连线方式举行。侵华日军遗属仓桥绫子向长春师范大学捐赠父亲谢罪碑的复刻品，她的父亲是侵华日军关东军宪兵部队的一员。她表示，希望谢罪碑永远矗立下去。 综合新华社记者报道 编辑：吴龙 新华社音视频部制作",
