    "author": "张兆卿,张馨文,张兆基",
    "description": "新华社法国斯特拉斯堡9月16日电（记者张兆卿 张馨文）欧盟委员会主席冯德莱恩16日在欧洲议会全会发表2026年“盟情咨文”时表示，重振经济是欧盟当前的首要任务。欧盟将加快推进单一市场改革，降低能源成本和行政负担，以提升经济竞争力。 冯德莱恩说，能源价格和借贷成本上升正给民众和企业带来压力，欧盟需要在保障财政可持续性的同时保护投资。她表示，欧盟委员会将提出进一步加快项目审批的建议，对符合战略利益的项目大幅提速，并继续削减企业特别是中小企业…",
    "content": "新华社法国斯特拉斯堡9月16日电（记者张兆卿 张馨文）欧盟委员会主席冯德莱恩16日在欧洲议会全会发表2026年“盟情咨文”时表示，重振经济是欧盟当前的首要任务。欧盟将加快推进单一市场改革，降低能源成本和行政负担，以提升经济竞争力。 冯德莱恩说，能源价格和借贷成本上升正给民众和企业带来压力，欧盟需要在保障财政可持续性的同时保护投资。她表示，欧盟委员会将提出进一步加快项目审批的建议，对符合战略利益的项目大幅提速，并继续削减企业特别是中小企业面临的行政负担。 在能源问题上，冯德莱恩表示，如果能源价格长期处于高位，就无法保…"
