    "pub_date": "2026-09-17 00:05:09",
    "author": "陆华东",
    "description": "新华社南京9月16日电（记者陆华东）16日晚，2026海峡两岸（昆山）中秋灯会亮灯仪式暨第六届海峡两岸青年文化月闭幕式在江苏省昆山市举行，约390名两岸企业家代表、青年代表等嘉宾参加活动。 本届灯会以“花开并蒂，灯映两岸”为主题，打造慧聚广场、周庄两大核心灯区。灯会期间，昆山将配套举办两岸艺术展、百戏游园会、森林“月下雅集”等多元活动，兼顾传统文化、潮流体验、惠民消费，丰富市民游客夜间文化生活，为两岸同胞搭建赏花灯、叙乡情、促交流的广阔…",
    "content": "新华社南京9月16日电（记者陆华东）16日晚，2026海峡两岸（昆山）中秋灯会亮灯仪式暨第六届海峡两岸青年文化月闭幕式在江苏省昆山市举行，约390名两岸企业家代表、青年代表等嘉宾参加活动。 本届灯会以“花开并蒂，灯映两岸”为主题，打造慧聚广场、周庄两大核心灯区。灯会期间，昆山将配套举办两岸艺术展、百戏游园会、森林“月下雅集”等多元活动，兼顾传统文化、潮流体验、惠民消费，丰富市民游客夜间文化生活，为两岸同胞搭建赏花灯、叙乡情、促交流的广阔平台。 海峡两岸关系协会会长张志军在致辞中表示，即将到来的中秋是中华民族共同的传…"
