    "content": "多名日本历史学者、民间和平人士16日在东京围绕九一八事变爆发95周年举行研讨会。与会者就“历史记忆与传承”这一主题，围绕战争记忆、加害责任以及和平理念传承等展开交流。当天研讨会上还举行了侵华日军谢罪碑复制品捐赠仪式。日中口述历史文化研究会成员、侵华日军后代仓桥绫子代已故父亲，向长春师范大学捐赠父亲谢罪碑的复制品。 仓桥的父亲大泽雄吉是侵华日军关东军宪兵部队的一员，曾在天津、北京、黑龙江省东宁市等地服役。1945年日本战败投降之际，大泽被苏联军队俘虏，后设法逃脱并辗转逃回日本。 作为曾经的日本初中教师，仓桥坦言，日本…"
