    "author": "陈泽安,蓝建中",
    "description": "新华社东京9月17日电（记者陈泽安 蓝建中）据日本气象厅消息，日本茨城县南部地区当地时间17日凌晨发生4.8级地震，首都东京震感明显。 日本气象厅说，地震发生于当地时间17日0时7分（北京时间16日23时7分），震中位于北纬36.1度、东经140.1度，震源深度约70公里。 日本气象厅还说，无需担心发生海啸灾害。",
    "content": "新华社东京9月17日电（记者陈泽安 蓝建中）据日本气象厅消息，日本茨城县南部地区当地时间17日凌晨发生4.8级地震，首都东京震感明显。 日本气象厅说，地震发生于当地时间17日0时7分（北京时间16日23时7分），震中位于北纬36.1度、东经140.1度，震源深度约70公里。 日本气象厅还说，无需担心发生海啸灾害。"
