    "content": "9月16日，香港特区行政长官李家超（中）在记者会上回答记者提问。新华社记者 陈铎 摄 新华社香港9月16日电（记者肖逸晨）香港特区行政长官李家超16日出席香港第一个五年规划和2026年施政报告记者会时应询表示，香港将继续深度参与深圳前海、广州南沙、珠海横琴、深港河套这4个粤港澳大湾区重大合作平台建设，与大湾区内其他城市共同推进优势互补、错位发展。 新华社记者在记者会上提问，香港未来将推出哪些创新举措、与粤港澳大湾区其他城市进行哪些新的互动，从而深化大湾区建设？李家超作上述表示。 李家超说，在大湾区4个重大合作平台中…"
