    "content": "新华社澳门9月16日电（记者齐菲、宋晨）离岛医疗综合体北京协和医院澳门医学中心两周年院庆暨医疗健康高峰论坛16日在澳门举办。论坛设平行学术论坛，围绕胰腺病、罕见病、护理及医学综合等多个领域展开深度交流。 澳门特区行政长官代表、特区政府社会文化司司长柯岚致辞表示，协和澳门医学中心是推动“一国两制”在卫生健康领域实践的重要合作项目、重大民生工程。未来，希望中心继续配合澳门公共医疗服务的动态需求，做好精准分流；充分发挥优势，持续提升澳门疑难重症和特色医疗服务水平，加强本地医疗人才培养，拓展国际医疗服务；探索成立境外医学研…"
