    "author": "胡浩,张研,秦宏",
    "description": "青山如黛、溪水潺潺。闽西的青山绿水间，毗邻“龙岩八景”之一“奇迈岚光”的龙岩市新罗区邓厝村，一座座古厝见证着红色历史。这里是革命前辈邓子恢的故乡。 村里有一口井，名为“思源泉”。思源泉的故事，在村里家喻户晓。 党员干部在龙岩市新罗区东肖街道邓厝村思源泉前重温入党誓词。（本图片由新罗区委宣传部提供） 1999年1月8日至12日，时任福建省委副书记习近平花了四天半的时间，走访部分闽西籍革命前辈的家乡，看望慰问老区群众。 “那时正是春节前，天…",
    "content": "青山如黛、溪水潺潺。闽西的青山绿水间，毗邻“龙岩八景”之一“奇迈岚光”的龙岩市新罗区邓厝村，一座座古厝见证着红色历史。这里是革命前辈邓子恢的故乡。 村里有一口井，名为“思源泉”。思源泉的故事，在村里家喻户晓。 党员干部在龙岩市新罗区东肖街道邓厝村思源泉前重温入党誓词。（本图片由新罗区委宣传部提供） 1999年1月8日至12日，时任福建省委副书记习近平花了四天半的时间，走访部分闽西籍革命前辈的家乡，看望慰问老区群众。 “那时正是春节前，天气很冷，路也不好走。习近平同志风尘仆仆走进革命先烈陈客嫲的女儿陈梅香老人家中时，…"
