    "author": "韩松,曹佩弦,田中全,宋立崑,鲁金博",
    "description": "9月15日，农民在嘉鱼县潘家湾镇蔬菜长廊栽种甘蓝菜苗。新华社记者 鲁金博 摄 新华社武汉9月16日电 题：中国的“甘蓝联合国”：以科技之力供给14亿人的餐桌 新华社记者曹佩弦、田中全 在湖北省嘉鱼县，平凡的甘蓝不再仅仅是一种蔬菜。它是一场静悄悄的“农业革命”的象征。 这个被称为“甘蓝联合国”的县，已成为中国食品供应链中的重要引擎，证明了即使是最常见的作物也能站在创新的最前沿。 嘉鱼甘蓝的故事是一次非凡的蜕变。“就在上世纪80年代，中国的…",
    "content": "9月15日，农民在嘉鱼县潘家湾镇蔬菜长廊栽种甘蓝菜苗。新华社记者 鲁金博 摄 新华社武汉9月16日电 题：中国的“甘蓝联合国”：以科技之力供给14亿人的餐桌 新华社记者曹佩弦、田中全 在湖北省嘉鱼县，平凡的甘蓝不再仅仅是一种蔬菜。它是一场静悄悄的“农业革命”的象征。 这个被称为“甘蓝联合国”的县，已成为中国食品供应链中的重要引擎，证明了即使是最常见的作物也能站在创新的最前沿。 嘉鱼甘蓝的故事是一次非凡的蜕变。“就在上世纪80年代，中国的甘蓝种子还依赖从日本和荷兰进口。把食品安全掌握在自己手中，是我们决心努力的方向。…"
