    "content": "新华社东京9月16日电（记者李子越 杨智翔）多名日本历史学者、民间和平人士16日在东京围绕九一八事变爆发95周年举行研讨会。与会者就“历史记忆与传承”这一主题，围绕战争记忆、加害责任以及和平理念传承等展开交流。 此次研讨会分东京和长春两个会场，以视频连线方式举行。多名与会者在发言中指出，日本帝国主义侵略给中国人民造成巨大牺牲。日本应正视侵略历史、反省战争责任，坚持和平宪法，并将战争加害记忆不断传承下去。 日本“继承和发展村山谈话会”理事长藤田高景在致辞中表示，九一八事变在战时长期被日本政府隐瞒，直到东京审判才逐渐为…"
