    "author": "尹炣",
    "description": "新华社科威特城9月16日电（记者尹炣）萨那消息：也门胡塞武装16日说，该组织当天发动导弹和无人机袭击，目标分别是位于沙特阿拉伯西部一处石油公司设施，以及沙特西南部一处空军基地。 胡塞武装控制的马西拉电视台当天援引该组织军事发言人叶海亚·萨雷亚的声明报道说，胡塞武装使用数十枚弹道导弹和无人机袭击了沙特西部城市延布的沙特阿美石油公司一处设施，后使用数枚弹道导弹“准确击中”了位于沙特西南部、靠近也门边境的阿西尔地区海米斯穆谢特的一处空军基地。…",
    "content": "新华社科威特城9月16日电（记者尹炣）萨那消息：也门胡塞武装16日说，该组织当天发动导弹和无人机袭击，目标分别是位于沙特阿拉伯西部一处石油公司设施，以及沙特西南部一处空军基地。 胡塞武装控制的马西拉电视台当天援引该组织军事发言人叶海亚·萨雷亚的声明报道说，胡塞武装使用数十枚弹道导弹和无人机袭击了沙特西部城市延布的沙特阿美石油公司一处设施，后使用数枚弹道导弹“准确击中”了位于沙特西南部、靠近也门边境的阿西尔地区海米斯穆谢特的一处空军基地。 萨雷亚在声明中表示，在沙特停止空袭并解除对也门胡塞武装控制区的封锁之前，该组织…"
