    "description": "9月16日，历经4年建设的世纪工程平陆运河建成通航，在中国与东盟两大市场之间，架起一条货畅其流、双向奔赴的互联互通新通道。 泰国开泰银行高级专家蔡伟才在接受新华社记者采访时表示，平陆运河开通将为东盟与中国跨境贸易发展创造新机遇。 记者：万后德 报道员：塔纳 新华社音视频部制作",
    "content": "9月16日，历经4年建设的世纪工程平陆运河建成通航，在中国与东盟两大市场之间，架起一条货畅其流、双向奔赴的互联互通新通道。 泰国开泰银行高级专家蔡伟才在接受新华社记者采访时表示，平陆运河开通将为东盟与中国跨境贸易发展创造新机遇。 记者：万后德 报道员：塔纳 新华社音视频部制作"
