    "content": "新华社北京9月16日电 欧盟委员会主席冯德莱恩16日表示，欧盟将建立一个“气候保险联盟”，以应对日益频发的极端天气事件，提高对气候灾害的保险覆盖范围。 9月14日，灭火飞机在克罗地亚布拉奇岛上空作业。新华社发（Pixsell图片社/兹沃尼米尔·巴利森摄） 世卫组织数据显示，欧洲是全球升温速度最快的大陆，升温速度约为全球平均水平的两倍。今年夏天，欧洲多地经历干旱、野火和多轮热浪天气，造成人员伤亡和财产损失。 欧盟表示，目前欧盟地区气候相关的经济损失中，只有四分之一在保险覆盖范围内。新出台的保险计划将试图解决这一问题。…"
