    "content": "新华社北京9月16日电 据美国媒体15日报道，美国移民执法人员去年9月在佐治亚州一场突击行动中抓捕300多名韩国工人后，涉事韩国工人正在采取法律措施，准备对美国联邦政府提起诉讼。 据美国有线电视新闻网报道，这些韩国工人已开始向美国国土安全部、移民与海关执法局、海关与边境保护局、联邦调查局以及司法部和劳工部等9个联邦机构提出行政索赔。根据美国相关法律，提出行政索赔是起诉美国联邦政府的必要程序。 3月23日，移民与海关执法局的执法人员在美国纽约拉瓜迪亚机场的出发安检处执勤。新华社记者张凤国摄 这些工人控诉，他们被捕后遭…"
