    "description": "新华社新加坡9月16日电（记者舒畅 毛鹏飞）泰国同柬埔寨16日在新加坡结束为期三天、针对两国重叠海域问题的首次国际调解会议。 此次调解依据《联合国海洋法公约》开展，是一种非裁决性程序，由中立的调解委员会协助双方寻求友好解决方案。 在15日的陈述中，柬埔寨副首相兼外交大臣布拉索昆说，柬方将优先寻求依据国际法与泰国签署条约，划定两国之间一条统一、适用于各类权益的海上边界。 泰国副总理兼外交部长西哈萨说，泰方旨在寻求海上边界划定问题的解决方案…",
    "content": "新华社新加坡9月16日电（记者舒畅 毛鹏飞）泰国同柬埔寨16日在新加坡结束为期三天、针对两国重叠海域问题的首次国际调解会议。 此次调解依据《联合国海洋法公约》开展，是一种非裁决性程序，由中立的调解委员会协助双方寻求友好解决方案。 在15日的陈述中，柬埔寨副首相兼外交大臣布拉索昆说，柬方将优先寻求依据国际法与泰国签署条约，划定两国之间一条统一、适用于各类权益的海上边界。 泰国副总理兼外交部长西哈萨说，泰方旨在寻求海上边界划定问题的解决方案。本次调解仅涉及泰柬在泰国湾的海上边界划定问题，不涉及陆地领土主权。 泰国外交部…"
