    "author": "陈柱佐",
    "description": "新华社南昌9月16日电（记者陈柱佐）记者16日从江西省九江市农业科学院获悉，近日，江西鄱阳湖流域传来生物多样性新发现——科研团队正式定名一种原生动物全球新物种“九江喇叭虫”。相关成果于8月底在国际权威动物分类学期刊《动物分类杂志》发表，新种基因条形码序列同步录入NCBI国际公共基因数据库。 据介绍，这一发现，进一步丰富了全球淡水原生生物种质资源库，为长江流域水生态持续向好、生物多样性本底持续增厚，提供了极具科学价值的微观实证。 这是科研…",
    "content": "新华社南昌9月16日电（记者陈柱佐）记者16日从江西省九江市农业科学院获悉，近日，江西鄱阳湖流域传来生物多样性新发现——科研团队正式定名一种原生动物全球新物种“九江喇叭虫”。相关成果于8月底在国际权威动物分类学期刊《动物分类杂志》发表，新种基因条形码序列同步录入NCBI国际公共基因数据库。 据介绍，这一发现，进一步丰富了全球淡水原生生物种质资源库，为长江流域水生态持续向好、生物多样性本底持续增厚，提供了极具科学价值的微观实证。 这是科研团队发现的新物种“九江喇叭虫”（拼版照片）。新华社发 此次新物种发现由农业农村部…"
