    "author": "杨进",
    "description": "眼下川西平原水稻迎来收割季。近日，在四川省眉山市东坡区太和镇永丰村的田地里，四川农业大学的科研团队对三块水稻田进行了测产，获得了亩均产超860公斤的产量。 四川农业大学马均教授团队，2003年就来到永丰村开展水稻试验示范。当年田块零散、没有高标准农田，基本靠人工耕种。2013年高标准农田建成落地，零散小田连片改造，实现全程机械化生产。以此为基础，团队持续选育适配本地的优质稻品种，研发配套栽培技术，探索稻药、稻菜粮经复合模式。 马均告诉记…",
    "content": "眼下川西平原水稻迎来收割季。近日，在四川省眉山市东坡区太和镇永丰村的田地里，四川农业大学的科研团队对三块水稻田进行了测产，获得了亩均产超860公斤的产量。 四川农业大学马均教授团队，2003年就来到永丰村开展水稻试验示范。当年田块零散、没有高标准农田，基本靠人工耕种。2013年高标准农田建成落地，零散小田连片改造，实现全程机械化生产。以此为基础，团队持续选育适配本地的优质稻品种，研发配套栽培技术，探索稻药、稻菜粮经复合模式。 马均告诉记者，他们主要是做两项工作，一个是水稻新品种的筛选，另外一个是新技术的研发和新技术…"
