    "description": "新华社日内瓦9月16日电（记者焦倩）为期三天的世界贸易组织2026年公共论坛15日在瑞士日内瓦开幕。同日，“机遇中国·创享未来”中国文化推介系列活动在世贸组织总部启动。 本次活动由中国国务院新闻办公室、中国常驻世贸组织代表团主办，五洲传播中心承办，旨在将人文交流有机融入全球经贸治理研讨，面向世贸组织成员代表、全球政商学界4000余名与会嘉宾推介中国文化理念。 作为活动重要组成部分，一场主题为“和合之声”的文化演出及招待会当晚在世贸组织临…",
    "content": "新华社日内瓦9月16日电（记者焦倩）为期三天的世界贸易组织2026年公共论坛15日在瑞士日内瓦开幕。同日，“机遇中国·创享未来”中国文化推介系列活动在世贸组织总部启动。 本次活动由中国国务院新闻办公室、中国常驻世贸组织代表团主办，五洲传播中心承办，旨在将人文交流有机融入全球经贸治理研讨，面向世贸组织成员代表、全球政商学界4000余名与会嘉宾推介中国文化理念。 作为活动重要组成部分，一场主题为“和合之声”的文化演出及招待会当晚在世贸组织临湖露台举行。 中国常驻世贸组织代表李詠箑致辞时表示，今年是中国加入世贸组织25周…"
