    "description": "金秋九月，天清云淡。位于湖北省大冶市的铜绿山国家考古遗址公园内，一座红铜瓦顶的建筑依山而筑，与千年古矿山自然地貌浑然一体。这就是铜绿山古铜矿遗址博物馆。记者近日随“活力中国调研行”采访团来到这里，探访千年矿冶遗址如何变身新潮公园。 博物馆屋顶复刻古代矿工工棚风貌，古朴韵味扑面而来。馆外，铜源广场气势恢宏，镌刻岁月的矿工足迹步道蜿蜒延伸。澄澈的九曲溪流穿园而过，泉塘映月，山水相依，勾勒出清幽雅致的生态景致。室外遗迹区内，连片生长的铜草花等…",
