    "content": "新华社北京9月16日电（记者伍岳）中共中央政治局委员、外交部长王毅16日在北京同伊朗外长阿拉格齐举行会谈。 王毅表示，中国愿意为解决国际争端发挥建设性作用，也愿同伊朗加强对话合作，维护好伊朗的正当权益。我们鼓励伊朗和美国保持理性和克制，尽快回归伊斯兰堡谅解备忘录，就各自关切的问题进行实质性磋商；我们支持伊朗同海湾国家开展对话，尊重彼此领土主权和国家安全；我们敦促各方采取有效措施，早日开放霍尔木兹海峡；我们不希望地区紧张向也门和红海方向进一步外溢。呼吁通过对话谈判解决问题。 王毅指出，习近平主席在访问埃及期间提出4点…"
