    "content": "新华社莫斯科9月16日电（记者侯鸣 王作葵）俄罗斯外交部网站16日发表声明说，俄外交部副部长鲁坚科当天会见日本驻俄大使武藤显时表示，日方持续执行的反俄路线，包括近期对俄总统普京访问南千岛群岛（日本称北方四岛）“歇斯底里”的反应，以及扩大对乌克兰的军事援助，使俄日实现对话正常化的前景更加渺茫。 声明说，俄方还强调了日本推进“再军事化”的危险性，包括与美国及其西方盟友在俄远东附近日益频繁的军事训练活动，以及在日本境内部署中程导弹系统。这些举措对俄国家安全以及东北亚的和平与稳定构成直接威胁。如果此类活动继续，俄将采取必要…"
