    "content": "新华社南宁9月16日电 特写：泪水与汗水，见证世纪运河扬帆起航时刻 新华社记者王楚然 9月16日10时25分，历史将铭记这一时刻，新中国成立以来第一条国家层面统筹建设的通江达海运河工程——平陆运河建成通航。 9月16日，在广西南宁港，一艘内贸船舶准备经平陆运河驶往海南洋浦港。新华社记者 曹祎铭 摄 此时的平陆运河“咽喉”马道枢纽两侧，江面水阔流平、澄波漾漾。汽笛长鸣声中，12艘货轮缓缓驶出，分赴内陆腹地与海的怀抱。 此刻的钦州港，海风猎猎、涛声澎湃。2艘江海联运船舶从海港首次驶入平陆运河航道，江海从此再无阻隔。 在…"
