    "content": "新华社台北9月16日电（记者黄扬、马欣然）《打开福建》系列丛书16日下午在台北举行新书发布会。 此次新书发表会由天龙文创出版事业有限公司与海峡文艺出版社共同主办，数十名出版业者、学者、文化界人士与会。与会人士普遍表示，期待台湾读者发现这部优质丛书，通过阅读进一步认识福建各地的文化特色，感受两岸在语言、信俗与生活习惯上的相通之处。 《打开福建》由海峡文艺出版社精心策划，是一套以福建地域文化为主题的大型丛书。首辑共10卷，涵盖福州、厦门、泉州、漳州、莆田、三明、南平、龙岩、宁德、平潭等九市一区，从历史文化、自然景观、地…"
