    "content": "新华社开罗9月16日电（记者张猛）喀土穆消息：苏丹民间机构和目击者16日说，苏丹西部西科尔多凡州一金矿发生坍塌事故，已造成63人死亡。 目击者告诉新华社记者，坍塌事故发生在15日，地点位于努胡德市的扎拉矿场。当地救援人员16日已从坍塌矿井中发现63具遇难者遗体，目前搜救仍在进行。 目击者还说，该矿场约有10座矿井，多座发生坍塌，井下被困人数或超过300人。由于矿井结构复杂、深度较大且缺乏专业救援设备，搜救工作面临较大困难。 苏丹民间机构“达尔哈马尔应急响应组织”也在社交媒体发文证实，扎拉矿场坍塌事故造成多人伤亡和失…"
