    "description": "新华社杭州9月16日电（记者段菁菁）全国政协副主席兼秘书长、中国经济社会理事会主席王东峰16日在杭州分别会见埃及参议长法里德，印尼国家经济委员会主席卢胡特，非洲经济社会理事会及类似组织联盟主席、摩洛哥经济社会环境理事会主席阿马拉，经济社会理事会和类似组织国际协会主席佩达斯，介绍中国经济社会发展和人民政协情况，围绕深化交往交流、加强务实合作、推动构建更加公平合理的全球治理体系、携手构建人类命运共同体等交换了意见。",
    "content": "新华社杭州9月16日电（记者段菁菁）全国政协副主席兼秘书长、中国经济社会理事会主席王东峰16日在杭州分别会见埃及参议长法里德，印尼国家经济委员会主席卢胡特，非洲经济社会理事会及类似组织联盟主席、摩洛哥经济社会环境理事会主席阿马拉，经济社会理事会和类似组织国际协会主席佩达斯，介绍中国经济社会发展和人民政协情况，围绕深化交往交流、加强务实合作、推动构建更加公平合理的全球治理体系、携手构建人类命运共同体等交换了意见。"
