    "content": "9月16日，嘉宾与空中客车天津A320系列飞机第二条总装线首架交付飞机合影。新华社记者 孙凡越 摄 新华社天津9月16日电 题：空客在华第二条总装线首架飞机交付 彰显中国高端制造竞争力 新华社记者宋瑞 空中客车设在中国也是亚洲的第二条A320系列飞机总装线16日交付首架飞机，标志着空客在中国乃至全球的工业布局迈入新发展阶段。 这架A320neo飞机由中国东方航空公司接收运营。东航于1985年接收中国引进的首架空客飞机，截至目前运营着中国规模最大的空客机队。 中国东方航空副总经理何晓群在交付仪式上表示，东航与空客已从…"
