    "description": "新华社东京9月16日电 题：日本民间办展揭露二战日军毒气战罪行 新华社记者李子越 梁晨 李林欣 “许多日本年轻人并不知道日军使用化学武器的这段历史。但我觉得，应该对此有所了解，所以特地来看一看。”日前，在一场由日本民间团体在横滨市举办的“日军毒气展”上，30岁的参观者右田这样对记者表示。 这场展览持续6天，几乎每天都有相关领域专家举办讲座。记者在现场看到，不大的展厅里，一块块展板揭露了一条完整而沉重的日军罪证链：毒剂生产、毒气弹装填、战…",
    "content": "新华社东京9月16日电 题：日本民间办展揭露二战日军毒气战罪行 新华社记者李子越 梁晨 李林欣 “许多日本年轻人并不知道日军使用化学武器的这段历史。但我觉得，应该对此有所了解，所以特地来看一看。”日前，在一场由日本民间团体在横滨市举办的“日军毒气展”上，30岁的参观者右田这样对记者表示。 这场展览持续6天，几乎每天都有相关领域专家举办讲座。记者在现场看到，不大的展厅里，一块块展板揭露了一条完整而沉重的日军罪证链：毒剂生产、毒气弹装填、战场埋设，再到战败后将大量化学武器遗弃在中国，贻害至今。 “日军毒气展”实行委员会…"
