    "description": "新华社日内瓦9月16日电 世界贸易组织2026年公共论坛期间，中方于16日在瑞士日内瓦举办主题为“产业政策与全球经贸治理协同”的专题研讨会，深入探讨产业政策的作用和影响，分析全球产业政策发展新趋势及新挑战，并就如何推进产业政策规则全球协同提出意见建议。 本次研讨会由清华大学组织，汇聚中美欧专家学者和联合国贸发会议代表，来自世贸组织成员政府、私营部门、学界和媒体的200多名代表参会。 清华大学文科资深教授、经济管理学院院长白重恩指出，由于…",
    "content": "新华社日内瓦9月16日电 世界贸易组织2026年公共论坛期间，中方于16日在瑞士日内瓦举办主题为“产业政策与全球经贸治理协同”的专题研讨会，深入探讨产业政策的作用和影响，分析全球产业政策发展新趋势及新挑战，并就如何推进产业政策规则全球协同提出意见建议。 本次研讨会由清华大学组织，汇聚中美欧专家学者和联合国贸发会议代表，来自世贸组织成员政府、私营部门、学界和媒体的200多名代表参会。 清华大学文科资深教授、经济管理学院院长白重恩指出，由于市场失灵普遍存在，产业政策的必要性毋庸置疑。同一产业政策在不同阶段的作用和影响不…"
