    "content": "新华社日本名古屋9月16日电（记者许仕豪、肖亚卓、赵紫羽）16日中午12点15分左右，中国体育代表团团部和部分队伍的参赛人员顺利抵达日本名古屋，准备参加即将开幕的亚运会。然而，飞机是准时到了，人却被困在机场附近，迟迟无法乘车赶往住地。 按照计划，当天抵达的各代表团要从机场附近坐大巴前往住所。然而下午2点，记者在机场交通中心仍然看到不少国家和地区的运动员“东倒西歪”就地等大巴，显得很疲惫。 记者与印度赛艇队教练攀谈起来，他说，队伍上午10点左右就落地了，但在交通中心等了4个多小时了，还是走不了。 韩国代表团成员在机场…"
