    "content": "新华社日本名古屋9月16日电（记者高萌）据中国代表团16日消息，女子拳击运动员吴愉、男子篮球运动员胡明轩将担任爱知·名古屋亚运会开幕式中国代表团旗手。 吴愉出生于贵州，现年31岁，先后拿下世锦赛、杭州亚运会、巴黎奥运会冠军。在2024年巴黎奥运会拳击女子50公斤级比赛中，她为中国队夺得金牌。 胡明轩出生于新疆维吾尔自治区，现年28岁，参加过男篮世界杯、亚洲杯、亚运会等国际大赛。他在2025年亚洲杯决赛中独得26分，中国队最终获得亚军，取得参加该赛事近十年来的最好成绩。 亚运会开幕式将于9月19日举行。"
